local a=require("fcs.comms.protocol")local b={}b.CMD_KIND="eh2_beacon_update"b.ACK_KIND="eh2_beacon_update_ack"b.CMD2_KIND="eh2_beacon_cmd"b.STATUS_KIND="eh2_beacon_status"b.OPS={enable=true,disable=true,verify=true,query=true,setPos=true,setInterval=true,reboot=true}function b.cmd(c,d,e)return{k=b.CMD2_KIND,op=c,token=d,args=e}end;function b.status(f,g)local h={k=b.STATUS_KIND,id=f}for i,j in pairs(g or{})do h[i]=j end;return h end;function b.validToken(k)return type(k)=="string"and k:gsub("%s","")~=""end;function b.command(d)return{k=b.CMD_KIND,token=d}end;function b.ack(f)return{k=b.ACK_KIND,id=f}end;function b.encode(l)return a.encode(l)end;function b.decode(m)local h=a.decode(m)if type(h)~="table"then return nil end;if h.k==b.CMD_KIND or h.k==b.ACK_KIND or h.k==b.CMD2_KIND or h.k==b.STATUS_KIND then return h end;return nil end;function b.accepts(l,n)if type(l)~="table"or l.k~=b.CMD_KIND then return false end;if not b.validToken(n)then return false end;if not b.validToken(l.token)then return false end;return l.token==n end;function b.acceptsCmd(l,n)if type(l)~="table"or l.k~=b.CMD2_KIND then return false end;if not b.OPS[l.op]then return false end;if not b.validToken(n)then return false end;if not b.validToken(l.token)then return false end;return l.token==n end;return b